-- ── Pipelines ────────────────────────────────────────────────────────────
insert into pipelines (module_id, label, position)
select mo.id, v.label, v.position
from (values
  ('leads', 'Lead Pipeline', 0),
  ('deals', 'Deal Pipeline', 10),
  ('contacts', 'Account Health', 20),
  ('tickets', 'Support Pipeline', 30)
) as v(module_slug, label, position)
join modules mo on mo.slug = v.module_slug;

insert into pipeline_steps (pipeline_id, label, swatch, position)
select pl.id, v.label, v.swatch::swatch, v.position
from (values
  ('Lead Pipeline', 'leads', 'New lead', 'slate', 0),
  ('Lead Pipeline', 'leads', 'Contacted', 'blue', 10),
  ('Lead Pipeline', 'leads', 'Qualified', 'indigo', 20),
  ('Lead Pipeline', 'leads', 'Statement received', 'purple', 30),
  ('Lead Pipeline', 'leads', 'Proposal sent', 'amber', 40),
  ('Lead Pipeline', 'leads', 'Closed', 'teal', 50),
  ('Deal Pipeline', 'deals', 'Application sent', 'slate', 0),
  ('Deal Pipeline', 'deals', 'Application received', 'blue', 10),
  ('Deal Pipeline', 'deals', 'Underwriting', 'purple', 20),
  ('Deal Pipeline', 'deals', 'Approved', 'green', 30),
  ('Deal Pipeline', 'deals', 'Equipment ordered', 'amber', 40),
  ('Deal Pipeline', 'deals', 'Installed', 'teal', 50),
  ('Deal Pipeline', 'deals', 'Live', 'lime', 60),
  ('Account Health', 'contacts', 'Onboarding', 'blue', 0),
  ('Account Health', 'contacts', 'Active', 'teal', 10),
  ('Account Health', 'contacts', 'At risk', 'amber', 20),
  ('Account Health', 'contacts', 'Churned', 'red', 30),
  ('Support Pipeline', 'tickets', 'Reported', 'orange', 0),
  ('Support Pipeline', 'tickets', 'Investigating', 'amber', 10),
  ('Support Pipeline', 'tickets', 'Awaiting merchant', 'purple', 20),
  ('Support Pipeline', 'tickets', 'Resolved', 'teal', 30)
) as v(pipeline_label, module_slug, label, swatch, position)
join modules mo on mo.slug = v.module_slug
join pipelines pl on pl.module_id = mo.id and pl.label = v.pipeline_label;

